const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={mode:'DEMO',signed:false,accounts:{'hello@example.com':{invited:true,role:'member'}},challenge:null,anonymousId:1,publicRisk:null,createdRooms:[],roomError:'',inviteListView:'actual',serverVersion:12,version:12,reviewedBaseVersion:12,role:'guest',authReturn:'rooms',authBack:'home',accountOpen:false,reviewSandbox:false,qaFlow:'anonymous',boardZoom:.65,boardExpanded:false,boardReferences:false,reviewIndex:-1,reviewContext:null,boardMode:'DEMO',boardRole:'all',ownerRiskAck:null,ownerRiskDraft:false,invitedAccount:false,inviteInput:'',inviteError:'',validatedInviteId:null,email:'hello@example.com',invite:false,inviteId:null,reviewed:null,auth:'login',otpError:'',otpSent:0,otpExpired:false,inviteConsumed:false,roomTTL:'24시간',risk:false,grant:false,publicId:'garden',grants:{},createdRoom:null,persist:false,retention:7,roomLabel:'우리의 다음 작은 생각',adminTab:'overview',dirty:false,saving:false,saveError:'',conflict:false,pending:null,nextInvite:3,lastInviteCode:null,invites:[{label:'새로운 친구를 위한 초대',status:'active',expiry:'내일 오후 6:00',code:'00000000-0000-4000-8000-000000000001'},{label:'금요일 작은 모임',status:'used',expiry:'오늘 오전 11:30',code:'00000000-0000-4000-8000-000000000002'}]};
const initial={mode:'DEMO',publicEnabled:true,publicRooms:3,publicCap:100,batch:2,messageTTL:30,readerWindow:300,readerCount:20,readWait:25,privateAnonymous:true,anonymousRooms:1,accountRooms:3,globalPrivate:50,defaultTTL:24,maxTTL:168,privateCap:10,messageBytes:4096,roomMessages:200,roomBytes:512,globalMemory:64,overflow:'reject',signup:'invite',inviteHours:24,inviteUses:1,emailHour:2,emailDay:3,resend:120,ipHour:30,ipDay:100,emailMonth:10000,budget:100,warning:80,persistence:true,retention:7,maxRetention:30};
let saved={...initial},draft={...initial},serverSettings={...initial};state.invites[0].expiresAt=Date.now()+86400000;state.invites[1].expiresAt=Date.now()+86400000;
function principal(){return state.signed?'account:'+state.email:'anonymous:'+state.anonymousId}
function activeInvite(v){return !!v&&v.status==='active'&&Number.isFinite(v.expiresAt)&&v.expiresAt>Date.now()}
function clearChallenge(){state.challenge=null;state.otpSent=0;state.otpExpired=false;state.otpError=''}
function issueChallenge(email,purpose){if(purpose==='signup'&&state.mode==='DEMO'&&(!state.invite||!activeInvite(state.invites.find(v=>v.code===state.inviteId)))){state.invite=false;go('invite/expired');return false}const now=Date.now();state.email=email;state.challenge={email,purpose,mode:state.mode,inviteId:purpose==='signup'&&state.mode==='DEMO'?state.inviteId:null,issuedAt:now,expiresAt:now+600000,consumed:false};state.otpSent=now;state.otpExpired=false;state.otpError='';return true}
function enterAuth(kind='login',origin=route()){clearChallenge();state.auth=kind;const authOrigin=['login','signup','verify','invite/valid','invite/demo'].includes(origin);if(!authOrigin)state.authBack=origin==='welcome'?'home':origin;state.authReturn=authOrigin?state.authReturn||'rooms':['about','home','welcome'].includes(origin)?'rooms':origin;go(kind)}
function cancelAuth(){const back=state.authBack||'home';clearChallenge();state.authReturn='rooms';state.authBack='home';state.invite=false;state.inviteId=null;state.validatedInviteId=null;go(back)}
function finishVerification(code){const challenge=state.challenge;if(!challenge||challenge.consumed){state.otpError='먼저 이메일로 인증번호를 요청해주세요.';redraw();return}if(challenge.expiresAt<=Date.now()||state.otpExpired){state.otpError='인증번호가 만료됐어요. 새 번호를 받아주세요.';redraw();$('#xOtp')?.focus();return}if(code!=='123456'){state.otpError='인증번호가 맞지 않아요. 6자리를 다시 확인해주세요.';redraw();$('#xOtp')?.focus();return}const wasExisting=!!state.accounts[challenge.email];let account=state.accounts[challenge.email];if(challenge.purpose==='signup'){const invitation=challenge.inviteId?state.invites.find(v=>v.code===challenge.inviteId):null;if(challenge.mode==='DEMO'&&!activeInvite(invitation)){clearChallenge();state.invite=false;go(invitation?.status==='revoked'?'invite/revoked':'invite/expired');return}if(!account){account={invited:challenge.mode==='DEMO',role:'member'};state.accounts[challenge.email]=account;if(invitation){invitation.status='used';state.inviteConsumed=true;}}}if(!account){clearChallenge();state.authReturn='rooms';state.invite=false;state.validatedInviteId=null;go('signup');toast('이메일을 확인했어요. 가입 절차를 먼저 진행해주세요');return}challenge.consumed=true;const next=state.authReturn&&!['login','home','welcome','about','signup','verify'].includes(state.authReturn)?state.authReturn:'rooms';state.email=challenge.email;clearChallenge();state.signed=true;state.role=account.role;state.invitedAccount=account.invited;state.invite=false;state.validatedInviteId=null;state.authReturn='rooms';state.authBack='home';state.accountOpen=false;state.risk=false;state.publicRisk=null;go(next.startsWith('admin/')&&state.role!=='admin'?'rooms':next);toast(challenge.purpose==='signup'&&wasExisting?'이미 가입된 이메일로 로그인했어요. 초대는 사용하지 않았어요.':'이메일 확인을 완료한 상태예요')}
function applyIdentityTransition(kind,role){clearChallenge();state.authReturn='rooms';state.authBack='home';state.accountOpen=false;state.invite=false;state.inviteId=null;state.validatedInviteId=null;state.risk=false;state.publicRisk=null;state.grant=false;state.persist=false;state.ownerRiskDraft=false;state.anonymousId++;state.role=kind==='logout'?'guest':role;state.signed=state.role!=='guest';state.invitedAccount=state.signed;$('#xDialog')?.close();go(state.role==='admin'?'admin/overview':state.signed?'rooms':'home');render()}
function riskAccepted(){return !!state.publicRisk&&state.publicRisk.owner===principal()&&state.publicRisk.roomId===state.publicId&&state.publicRisk.version==='public-risk-v1'}
function grantKey(id=state.publicId){return principal()+'|'+id+'|milo'}
function grantHistory(id=state.publicId){return state.grants[grantKey(id)]}
function grantRecord(id=state.publicId){const g=grantHistory(id);return g&&g.owner===principal()&&g.roomId===id&&g.agent==='milo'&&!g.revoked&&g.expiresAt>Date.now()?g:null}
function activeGrants(){return Object.values(state.grants).filter(g=>g.owner===principal()&&g.agent==='milo'&&!g.revoked&&g.expiresAt>Date.now())}
function privateMaxHours(){return Math.max(1,Math.min(saved.maxTTL,state.signed?168:24))}
function ttlLabel(hours){return hours%24===0&&hours>=48?hours/24+'일':hours+'시간'}
function parseTTL(value){const match=/^(\d+)(시간|일)$/.exec(value||'');return match?Number(match[1])*(match[2]==='일'?24:1):NaN}
function canStore(){return state.signed&&saved.persistence&&(state.mode==='HOSTED'||state.invitedAccount)}
function activePrivateRooms(){return state.createdRooms.filter(r=>!r.closed&&r.expiresAt>Date.now())}
function ownedPrivateRooms(){return activePrivateRooms().filter(r=>r.owner===principal())}
function roomLimitError(){if(!state.signed&&!saved.privateAnonymous)return '지금은 로그인 없이 개인 방을 만들 수 없어요.';const quota=state.signed?saved.accountRooms:saved.anonymousRooms;if(quota<=0||ownedPrivateRooms().length>=quota)return '동시에 열 수 있는 개인 방 '+quota+'개를 모두 사용하고 있어요. 열린 방을 닫은 뒤 다시 만들어주세요.';if(activePrivateRooms().length>=saved.globalPrivate)return '지금은 서비스의 개인 방 한도에 도달했어요. 잠시 후 다시 시도해주세요.';return ''}
function roomUnavailable(kind='missing'){const expired=kind==='expired',invalid=kind==='invalid';return frame(`<section class="restricted-card"><span class="eyebrow">A LITTLE ROOM, JUST FOR NOW</span><h1>${expired?'이 방은 문을 닫았어요.':invalid?'초대를 확인할 수 없어요.':'방을 찾을 수 없어요.'}</h1><p>${expired?'유효시간이 지났거나 방의 주인이 닫았어요.':invalid?'링크가 잘못됐거나 입장 권한이 취소됐을 수 있어요.':'이 시안은 새로고침하면 가상 방이 초기화돼요. 다른 예시 방으로 바꾸어 보여주지 않아요.'}</p><a href="#rooms" class="btn primary">대화방으로 돌아가기</a></section>`,'x-wrap')}
function closeCreatedRoom(){if(currentRoomId==='new'&&state.createdRoom){state.createdRoom.closed=true;const record=state.createdRooms.find(r=>r.id===state.createdRoom.id);if(record)record.closed=true}}

